def figures():
 cr=read('cr2');sc=read('cenarios');p=read('painel');su=read('suporte_design');national=read('nacional_dinamica')
 for per in ['Total','Pré']:
  d=sc[sc.periodo==per].sort_values('estimate');fig,ax=plt.subplots(figsize=(11,10));ax.errorbar(d.estimate,np.arange(len(d)),xerr=np.array([d.estimate-d.low,d.high-d.estimate]),fmt='o',color='#245e6b',capsize=3);ax.set_yticks(np.arange(len(d)),d.exposicao);ax.axvline(0,color='black',ls='--');ax.set(xlabel='Mudança acumulada em pp: 0 → mediana positiva de cobertura; IC CR2',title='Precisão no cenário observado — '+per);fig.tight_layout();fig.savefig(FIG/('forest_'+per+'.svg'));plt.close(fig)
 for key,d in cr[cr.endpoint.str.startswith(('beta_','C_'))].groupby(['periodo','coluna','especificacao']):
  fig,axes=plt.subplots(1,2,figsize=(11,4))
  for ax,kind in zip(axes,['beta_','C_']):
   z=d[d.endpoint.str.startswith(kind)].copy();z['h']=z.endpoint.str.split('_').str[-1].astype(int);z=z.sort_values('h');ax.plot(z.h,z.estimate,'o-',label='Estimativa');ax.fill_between(z.h,z.low,z.high,alpha=.22,label='IC95% CR2 ponto a ponto');ax.axhline(0,color='black',ls='--');ax.set(xlabel='Lag' if kind=='beta_' else 'Horizonte',ylabel='pp / unidade de cobertura0–1',title='Perfil incremental' if kind=='beta_' else 'Resposta acumulada');ax.legend(fontsize=8)
  fig.suptitle(' · '.join(key));fig.tight_layout();slug=''.join(x if x.isalnum() else '_' for x in '_'.join(key));fig.savefig(FIG/(slug+'.svg'));plt.close(fig)
 for key,d in national.groupby(['periodo','coluna']):
  fig,ax=plt.subplots(figsize=(8,4));ax.plot(d.h,d.C,'o-');ax.fill_between(d.h,d.C_low,d.C_high,alpha=.2);ax.axhline(0,color='black',ls='--');ax.set(xlabel='Horizonte',ylabel='pp / unidade cobertura nacional',title='Acumulado dinâmico — '+str(key)+'; delta/HAC ponto a ponto');fig.tight_layout();fig.savefig(FIG/('nacional_'+key[1]+'.svg'));plt.close(fig)

def documentation():
 cl=read('classificacao');cr=read('cr2');n=read('nacional_robustez');su=read('suporte_design');ext=read('validacao_bootstrap_externa');lines=['# DLM — validação final e resultados','', 'Correções numéricas/metodológicas novas são separadas dos resultados preservados. ΔI/cobertura/splineK12/UF+mês-ano continuam principais. CR2 é inferência principal para contrastes; bootstrap é verificação, não votação com DK/CR1. Sem Granger/SARIMAX/merge.','', '## Metadados e suporte','Os46rótulos J alternativo foram corrigidos sem alterar coeficientes. Suporte da janela e do contraste não equivale a suporte contemporâneo nem a df.','',su[(su.coluna=='tipo_onda_de_frio')&(su.especificacao=='Principal')].to_markdown(index=False),'','## Bootstrap externo',ext.to_markdown(index=False),'','Escalares e interação:4999pesos idênticos, diferenças estatísticas abaixo1e-5. Conjuntos:99refits independentes statsmodels; pacote instalado não suporta hipótese múltipla. Isso valida implementação, não cobertura em suporte fraco. IC por grade não limitado não é convertido em limites finitos.','', '## Inferência principal','']
 for spec in ['Principal','Sazonalidade UF','Exclui DF']:
  z=cr[(cr.especificacao==spec)&(cr.endpoint=='acumulado')];lines.append(f'{spec}: {int((z.q<.05).sum())} acumulados BH/CR2; {int(z.status.ne("calculado").sum())} indisponíveis.')
 lines+=['','## Classificação multidimensional',cl.to_markdown(index=False),'','## Nacional central: sensibilidades',n.to_markdown(index=False),'','A seleção dos4centrais vem da revisão anterior, não de novos p. Retirar respostas pode mudar amostra/estimando e lags dos episódios permanecem em equações vizinhas. Perda de rejeição com amostra menor não prova dependência causal de um mês. HAC respeita calendário. Delta usa covariância completa AR/exposição; IC ponto a ponto.','', '## Alterações no TCC','1. Corrigir J/metadados; 2. inserir suporte do design/contraste e incerteza apropriada; 3. adicionar sazonalidade UF e DF; 4. distinguir modelos separados/conjuntos; 5. apresentar influência nacional e resposta recursiva; 6. substituir robustez como votação por análise de pressupostos; 7. resultados nulos não são equivalência; 8. exposição registrada não atribui mudança climática; 9. preservar histórico e rastreio.','', '## Limites','Observacional; municípios sem população/área/intensidade; datas de registro não duração; poucas UFs informativas; seleção J/AR condicionada; erros de mensuração não entram nos IC; spillovers não estimados; CR2 assume clusters independentes; dependência transversal pode permanecer; nacional sujeito a confundimento agregado.']
 (ROOT/'docs/dlm_validacao_final_resultados.md').write_text('\n\n'.join(lines))

TOPICS=[
('Resumo para a orientadora','O objetivo é avaliar associações temporais defensáveis, não obter significância. Os resultados históricos são preservados. O painel e o nacional usam variações e estimandos diferentes. Consulte os resultados abaixo antes de concluir ausência ou presença de associação.'),
('Pergunta do TCC e alcance do DLM','O DLM relaciona exposição registrada nos meses0–12 com mudanças mensais na taxa. Sem identificação causal, não atribui alterações do crédito a mudanças climáticas antropogênicas. Uma associação pode refletir confundidores estaduais, mensuração ou efeitos indiretos.'),
('O que mudou nas duas revisões','Histórico: log1p(registros), DLM irrestrito/BIC/K3 e cluster. Primeira revisão: cobertura municipal, splineK12 e inferência ampliada. Validação final: corrige46metadados J, integra suporte, valida bootstrap externo, acrescenta sazonalidade UF/DF/modelos conjuntos e audita influência nacional.'),
('Estrutura e qualidade dos dados','27UFs×144meses,2013–2024. Pré termina jan/2020. A construção de ΔI e12lags deixa132meses no total e73no pré. Não se usa informação pré2013. CSV/parquet e Atlas reconciliados. As amostras dos placebos terminam antes por exigir leads. Dois cenários pré (calor/baixa umidade e barragens) não atingem triagem inicial e permanecem na família48, sem estimativas substantivas.'),
('Auditoria do Atlas','40.339registros,40.238chaves municipais,101repetições,0duplicatas exatas. B usa UF+município+data exata+COBRADE: ocorrência municipal, não tempestade regional única. Datas/protocolos e contagens anuais abaixo permitem avaliar cadastro, sem fabricar duração física.'),
('Taxonomia e interpretação climática','Grupos administrativos não formam hierarquia exclusiva de tipologias. Códigos12/13/14 indicam clima/hidro;11/15 naturais não diretamente climáticos;2 tecnológicos. Movimentos de massa podem ter chuva como gatilho não identificado pelo código. Chuvas Intensas13310 é divergência nome/código;14140 descreve baixa umidade, não isola calor. Nenhuma categoria apagada.'),
('Exposição principal e alternativas','Cobertura=C/municípiosUF, escala0–1. Mede extensão municipal registrada, não intensidade/população/área. A/B/C em log1p permanecem sensibilidades, com unidades e estimandos distintos. DF tem denominador1, avaliado por exclusão. Um aumento10pp de cobertura multiplica β/C por0,1.'),
('Estimando e identificação pelos FE','UF FE remove diferenças permanentes; mês-ano remove choques comuns nacionais. Identificação vem da exposição relativa das UFs no mesmo mês. Sem pesos, é associação de uma projeção com observações estaduais de igual peso, não necessariamente média aritmética de efeitos heterogêneos. PesosCA2013 mudam a importância das UFs.'),
('K12 não é duração de12meses','O horizonte máximo dá oportunidade de associações curtas/lentas. Não declara persistência por12meses nem igualdade entre tipologias. K3/BIC anterior também não demonstrava término após3meses. Ausência de lags além12 é restrição do modelo.'),
('Smooth DLM e spline','Z_j=ΣX(t−k)B_j(k);β=Bθ;Vβ=B Vθ B′. Spline natural com3/4parâmetros impõe suavidade; J é selecionado por BIC na revisão e mantido, não por p. Inferência é condicionada à base, sem incorporar incerteza de seleção. Almon e irrestritos são comparações limitadas.'),
('Suporte bruto, efetivo e da janela','Uma UF sem x0positivo pode contribuir por lags anteriores. Exposição bruta, contemporânea e janela são exibidas separadamente. Rank completo permite cálculo, mas não garante informação dispersa. Triagem da janela não substitui concentração ou dfCR2.'),
('Concentração e influência','N_eff da exposição descreve soma de exposição. Leverage depende da matriz residualizada; contraste mede informação geométrica para C12. Nenhum é dfSatterthwaite. Top1/top2 altos restringem generalização. Uma retirada pode mudar suporte e estimando, não confirmar inexistência.'),
('Resultados gerais','A tabela abaixo compara inferências. Rejeição nominal não é rejeição apósBH. Indisponível não é p=1observado. Não exigir consenso como votação: CR2/cluster assumem independência entre UFs; DK utiliza argumento temporal para dependência transversal.'),
('Resultados por grupo','Selecione grupos no painel de resultados. Cada agregado tem sua curva e mistura mecanismos. Um acumulado próximo de zero pode coexistir com perfil transitório. IC amplo não demonstra efeito pequeno. Grupos tecnológicos/não climáticos não fundamentam atribuição climática.'),
('Resultados por tipologia','Selecione tipologias no painel. Modelos separados não identificam efeito exclusivo da categoria. Sobreposição e exposições correlacionadas são auditadas; os modelos conjuntos limitados usam três agregadosCOBRADE, não todas as tipologias.'),
('Perfis incrementais β_k','β_k mede associação com ΔI no lagk de um pulso, mantendo demais exposições previstas no modelo. Pontos/linhas são estimativas; intervalosCR2 são ponto a ponto quando disponíveis. Não declarar duração pelo último intervalo que exclui zero. O contemporâneo não demonstra precedência.'),
('Curvas acumuladas C(h)','C(h)=Σ0..hβ_k usa covariâncias completas. Para pulso isolado em ΔI, soma descreve mudança associada na taxa atéh, condicional à especificação. Reversão pontual não é reversão robusta. Uma exposição repetida requer superposição dos pulsos; não confundir com pulso isolado.'),
('Contemporâneo versus defasado','Σ1..12β e reestimação semβ0 são objetos distintos: a spline/domínio e coeficientes mudam. A robustez somente defasada foi preservada, sem usar β0como precedência. A tabela da multiverse mostra a nova dimensão correta.'),
('Placebos','Leads1–3 servem para desalinhamento/sazonalidade/confundimento. Exposições persistentes podem correlacionar leads e lags; não rejeitar não prova exogeneidade. Tabelas preservadas trazem FDR própria; nacional central tem família4 exploratória.'),
('Pré/pós','Pós=fev/2020, data da resposta. γtesta mudança no perfil, não comparação de p em recortes sobrepostos. Acumuladospré, pós e diferença usam covariância completa. Exposições anteriores podem responder no pós. Data é convenção de comparação, não início epidemiológico exato.'),
('Robustez pandêmica','Exclui equações mar/2020–dez/2021, com lags calculados antes da exclusão. Exposições pandêmicas ainda podem entrar em2022. Estima associação fora das respostas atípicas, não uma amostra completamente livre de pandemia. A tabela corrigida preserva os coeficientes.'),
('Sazonalidade específica por UF','UF×mês do calendário controla padrões recorrentes próprios das UFs, além de choques nacionais de cada mês-ano. Absorção foi conferida com FE explícitos e rank sem redundâncias. Pode reduzir informação: estabilidade e IC precisam ser lidos juntos.'),
('FE nacionais versus regionais','Região×mês-ano absorve choques regionais de cada data. Difere de sazonalidadeUF que controla padrões anuais recorrentes. Ambos podem remover variação substantiva comum da exposição. Não reduzir controles para produzir rejeições.'),
('Não ponderado versus ponderado','Pesos fixos pela carteira média2013 evitam pesos contemporâneos. A associação ponderada enfatiza UFs relevantes na carteira-base, sem representar necessariamente um efeito causal nacional. Compare cenários/sinais e precisão, não só p.'),
('Exposições separadas versus conjuntas','Três blocosCOBRADE/J3/K12 condicionam a associação de um agregado aos outros. O estimando muda. Correlações x0 e blocos apósFE informam colinearidade. Nenhum efeito exclusivo de tipologia é identificado por essa extensão; spillovers permanecem limitação.'),
('Cluster, CR2, bootstrap e DK','CR2/Satterthwaite é principal para contrastes, HTZ para conjuntos quando disponível. WCR11 restringe H0e preserva clusterUF; singularidade torna inferência indisponível. DK12 é sensibilidade. Bandas antigasCR1/t26 estão rotuladas; não substituem IC robusto em exposição concentrada.'),
('Validação externa do bootstrap','Escalares/acumulados e interação comparados comwildboottest0.3.2/4999pesos idênticos. Conjuntos comparados em99refits comstatsmodels/cov_cluster porque o pacote instalado só suporta escalar. Diferenças em estatísticas/numeradores/covariâncias foram verificadas. Valida código, não garante cobertura sob suporte fraco.'),
('Multiverse e estabilidade','Mudanças são uma por vez: spline/exposição/horizonte/FE/pesos/pandemia. RótulosJ corrigidos, coeficientes anteriores reconciliados. Estabilidade mostra alteração de sinal e diferença emSECR2, sem classificar por qualquer pisolado. Não executar produto cartesiano.'),
('DLM nacional complementar','TI_BR=100ΣCI/ΣCA, não média simples. ΔI, splineK12/J3, sazonalidade/tendência, AR0/1/2BIC eHAC12. Quatro acumulados e dez conjuntosBH/HAC na revisão anterior permanecem como referência; sensibilidades centrais não substituem a família48.'),
('Influência temporal nacional','Retirar anos mantém o calendário e lags já construídos. Três maiores meses são escolhidos pela exposição, não por resíduos/p. Janela dominante remove equações do mês máximo e12seguintes. Mudança de precisão/amostra não prova dependência causal de um episódio. Compare sinais, magnitudes eIC.'),
('Soma direta versus dinâmica total','Com AR na dependente, resposta r(h)=β_h+Σφ_j r(h−j). Cdin soma essas respostas e pode continuar após12. Delta/HAC usa covariância completa exposição/AR e cruzada; IC ponto a ponto. EstabilidadeAR é checada. Não confundir C12direto eC24dinâmico.'),
('Precisão e relevância prática','Cenário0→mediana positiva é observado e específico da exposição/período. Estimativa/IC são pp. IC com ambos sinais significa grande incerteza de direção; não equivalência. Não usamos potência observada nem margem de irrelevância escolhida após resultados.'),
('Relação com Granger','Granger foi apenas recuperado: Granizo exploratório sensível à inferência/especificação. Avalia informação precedente em séries nacionais transformadas; painelDLM avalia associação relativa UF-mês. Não se força concordância nem se reexecuta Granger. SARIMAX não foi executado.'),
('Limitações remanescentes','Observacional; mensuração administrativa; duração física desconhecida; heterogeneidade não modelada plenamente; intensidade/população ausentes; FE não eliminam confundidoresUF-tempo; spillovers; dependência entreclusters; baixa informação efetiva; seleção spline/AR condicional. Precisão de IC não incorpora mensuração.'),
('Conclusões e mudanças no TCC','Atualizar unidade/taxonomia, metadados, suporte do design, inferência/bandas, estimandos, sazonalidadeUF, modelos conjuntos e influência nacional. Retirar afirmação de Onda de Frio histórica robusta. Ausência de perfil defensável não significa ausência de impactos. O texto deve distinguir exposição a desastres de atribuição à mudança climática.')]

